using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEditor;using ElDespacho;
public sealed class AccessibilityValidationProbe:MonoBehaviour {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;DespachoGame game;DeskMenus menus;AccessController access;List<string> lines=new List<string>();int errors,warnings;
 object Get(string n)=>typeof(DespachoGame).GetField(n,F).GetValue(game);void Call(string n,params object[] a)=>typeof(DespachoGame).GetMethod(n,F).Invoke(game,a);
 void Check(bool ok,string name){lines.Add((ok?"PASS ":"FAIL ")+name);File.WriteAllLines("Logs/Accessibility-v09.txt",lines);if(!ok)throw new Exception(name);}
 void Log(string m,string stack,LogType type){if(type==LogType.Warning)warnings++;if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert){errors++;lines.Add(m+stack);File.WriteAllLines("Logs/Accessibility-v09.txt",lines);EditorApplication.Exit(1);}}
 string State(){var s=game.CaptureSave();s.utcTicks=1;return JsonUtility.ToJson(s);}
 IEnumerator Tick(){access.Refresh();yield return null;yield return null;yield return null;}
 IEnumerator Start(){Directory.CreateDirectory("Logs");Application.logMessageReceived+=Log;yield return null;yield return null;game=FindAnyObjectByType<DespachoGame>();menus=game.GetComponent<DeskMenus>();access=AccessController.Instance;
  Check(access!=null&&!AccessPreferences.Current.Reflow,"defaults retain original presentation");
  menus.Resume();game.StartFromMenu();Call("ShowOffice");yield return Tick();
  AccessPreferences.Current.simpleDocuments=true;var d=(DeskDocument)Get("deskDocument");d.AccessSelect();Check(d.AccessSelected&&!d.CanDecide,"select without opening");Check(AccessController.CancelOrBack()&&!d.AccessSelected,"escape cancels without pausing");
  d.AccessSelect();d.AccessPlace();d.AccessPlace();yield return new WaitForSecondsRealtime(.4f);Check(d.CanDecide&&(bool)Get("documentOpened"),"simplified placement invokes real opening once");
  var stamp=game.GetComponentsInChildren<StampTool>().First();access.SelectStamp(stamp);Check(!(bool)Get("cardAnswered"),"stamp selection previews without deciding");Check(AccessController.CancelOrBack(),"stamp cancellation");access.SelectStamp(stamp);stamp.AccessApply();yield return Tick();Check((bool)Get("cardAnswered"),"simplified stamp applies real decision");string state=State();stamp.AccessApply();Check(state==State(),"duplicate simplified stamp ignored");
  yield return new WaitForSecondsRealtime(.4f);Call("ArchiveCard");yield return new WaitForSecondsRealtime(.4f);yield return Tick();Check(!(bool)Get("cardAnswered"),"next card after simplified decision");
  AccessPreferences.Current.keyboard=true;var entries=access.Snapshot();var select=entries.First(e=>e.text.Contains("Seleccionar expediente"));select.action();yield return Tick();entries=access.Snapshot();entries.First(e=>e.text.Contains("Colocar expediente")).action();yield return new WaitForSecondsRealtime(.4f);Check((bool)Get("documentOpened"),"keyboard action path opens document without mouse");
  state=State();menus.ShowSettings(0);access.SetReadingView(true);yield return Tick();
  foreach(float text in new[]{.75f,1f,1.25f,1.5f,1.75f})foreach(float scale in new[]{.8f,.9f,1f,1.1f,1.2f}){AccessPreferences.Current.textScale=text;AccessPreferences.Current.interfaceScale=scale;DeskPreferences.Current.highContrast=true;yield return Tick();var flow=access.transform.Find("Accessibility").GetComponentsInChildren<ScrollRect>().First();Check(flow.content.rect.height>0&&flow.viewport.rect.width>0,"reflow layout text "+text+" interface "+scale);foreach(var t in flow.content.GetComponentsInChildren<Text>())Check(t.preferredHeight<=t.rectTransform.rect.height+2,"text fits scroll row: "+t.text.Substring(0,Math.Min(20,t.text.Length)));}
  Check(state==State(),"visual settings leave campaign and tutorial unchanged in menus");
  foreach(int cat in new[]{0,1,2,3}){menus.ShowSettings(cat);yield return Tick();Check(access.Snapshot().Any(e=>e.action!=null),"settings category actions "+cat);}
  menus.ShowPause();yield return Tick();Check(access.Snapshot().Any(e=>e.text.Contains("GUARDAR")),"pause save actions exposed");menus.ShowSlots(false);yield return Tick();Check(access.Snapshot().Any(e=>e.text.Contains("VOLVER")),"load screen navigation exposed");typeof(DeskMenus).GetMethod("ShowHelp",F).Invoke(menus,null);yield return Tick();Check(access.Snapshot().Any(e=>e.text.Contains("12.")),"all twelve lesson links exposed");
  menus.Resume();Call("ShowMap");yield return Tick();Check(access.Snapshot().Any(e=>e.action!=null&&e.text.Contains("Sin visitar")),"map action semantic labels");
  Check(!string.Join(" ",access.Snapshot().Select(e=>e.text)).Contains("Korovia"),"future country name not exposed by accessible snapshot");
  var country=((List<Country>)Get("countries")).First();Call("StartVisit",country);yield return Tick();Check(access.Snapshot().Any(e=>e.action!=null&&e.text.Contains("ALIANZA")),"diplomatic decisions remain reachable");
  foreach(int tab in new[]{0,1,2,3}){typeof(DespachoGame).GetField("docTab",F).SetValue(game,tab);Call("ShowVisit");yield return Tick();Check(access.Snapshot().Any(e=>e.action==null&&e.text.Length>80),"report content readable tab "+tab);}
  AccessPreferences.Current.simpleLanguage=true;AccessPreferences.Current.symbols=true;yield return Tick();var lesson=TutorialManager.Instance.Steps.First(x=>x.persistentId=="questions");Check(TutorialLessons.Text(lesson,2).Contains("2 preguntas"),"simplified tutorial uses real question limit");
  access.ShowSettings();yield return Tick();var inputSettings=Instantiate(UnityEngine.InputSystem.InputSystem.settings);inputSettings.editorInputBehaviorInPlayMode=UnityEngine.InputSystem.InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;inputSettings.backgroundBehavior=UnityEngine.InputSystem.InputSettings.BackgroundBehavior.IgnoreFocus;UnityEngine.InputSystem.InputSystem.settings=inputSettings;var keyboard=UnityEngine.InputSystem.InputSystem.AddDevice<UnityEngine.InputSystem.Keyboard>();for(int focusStep=0;focusStep<5;focusStep++){UnityEngine.InputSystem.InputSystem.QueueStateEvent(keyboard,new UnityEngine.InputSystem.LowLevel.KeyboardState(UnityEngine.InputSystem.Key.Tab));yield return Tick();UnityEngine.InputSystem.InputSystem.QueueStateEvent(keyboard,new UnityEngine.InputSystem.LowLevel.KeyboardState());yield return Tick();}UnityEngine.InputSystem.InputSystem.QueueStateEvent(keyboard,new UnityEngine.InputSystem.LowLevel.KeyboardState(UnityEngine.InputSystem.Key.Enter));yield return Tick();UnityEngine.InputSystem.InputSystem.QueueStateEvent(keyboard,new UnityEngine.InputSystem.LowLevel.KeyboardState());yield return Tick();UnityEngine.InputSystem.InputSystem.RemoveDevice(keyboard);Check(access.CustomPage=="Visual","keyboard focus activates accessibility category");menus.ShowPause();yield return Tick();state=State();AccessPreferences.Current.mono=true;AccessPreferences.Current.softAudio=true;AccessPreferences.Current.navigationHelp=true;AccessPreferences.Current.glossary=true;AccessPreferences.Current.visualSounds=true;AccessPreferences.Current.narrationVolume=.4f;AccessPreferences.Current.speechRate=-2;Check(AccessPreferences.Current.Save(),"settings saved separately");AccessPreferences.Current.textScale=1;AccessPreferences.Load();Check(AccessPreferences.Current.textScale==1.75f&&AccessPreferences.Current.mono&&AccessPreferences.Current.narrationVolume==.4f,"preferences reload from disk");Check(state==State(),"preference reload leaves campaign untouched");Check(!JsonUtility.ToJson(game.CaptureSave()).Contains("narrationVolume"),"accessibility excluded from campaign schema");
  var samples=new[]{1f,-1f,.6f,.2f};AccessAudioFilter.Process(samples,2,true,false,new float[8]);Check(Mathf.Approximately(samples[0],samples[1])&&Mathf.Approximately(samples[2],samples[3]),"stereo downmix equal channels");samples=new[]{1f,-1f,1f,-1f};AccessAudioFilter.Process(samples,1,false,true,new float[8]);Check(samples.Max(x=>Mathf.Abs(x))<1,"comfort filter attenuates sharp changes");
  AccessPreferences.Current.narration=true;access.Speech.Say("Prueba de narración local.",true);yield return new WaitForSecondsRealtime(3);Check(access.Speech.Running&&access.Speech.Ready&&access.Speech.Accepted>0&&access.Speech.Error=="","Windows TTS worker starts without reported error: "+access.Speech.Error);access.Speech.Repeat();access.Speech.Stop();access.Speech.Dispose();Check(!access.Speech.Running,"narration stop and worker disposal");AccessPreferences.Current.narration=false;
  menus.SaveSlot(1);Check(DeskSaveStore.TryRead(1,out var saved,out _),"accessible preferences coexist with campaign save");menus.LoadSlot(1);yield return Tick();Check(AccessPreferences.Current.mono&&AccessPreferences.Current.textScale==1.75f,"load does not overwrite accessibility");
  Check(errors==0&&warnings==0,"no runtime errors or warnings");lines.Add("COMPLETE "+lines.Count(x=>x.StartsWith("PASS "))+" PASS; automated Play Mode events and fixtures; no physical or hearing test");File.WriteAllLines("Logs/Accessibility-v09.txt",lines);File.WriteAllText("Logs/AccessPrefsTestDirectory.txt",DeskPreferences.TestDirectory);EditorApplication.Exit(0);
 }
}
public static class AccessibilityValidationRunner {
 public static void Persistence(){DeskPreferences.TestDirectory=File.ReadAllText("Logs/AccessPrefsTestDirectory.txt");AccessPreferences.Load();bool ok=AccessPreferences.Current.textScale==1.75f && AccessPreferences.Current.mono;File.WriteAllText("Logs/Accessibility-restart.txt",ok?"PASS separate Unity process restores accessibility preferences":"FAIL preferences after process restart");EditorApplication.Exit(ok?0:1);}
 public static void Run(){SessionState.SetBool("Access09",true);SessionState.SetString("AccessDir09",Path.Combine(Path.GetTempPath(),"Despacho09-"+Guid.NewGuid().ToString("N")));EditorApplication.EnterPlaymode();}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Before(){if(!SessionState.GetBool("Access09",false))return;DeskSaveStore.TestDirectory=SessionState.GetString("AccessDir09","");DeskPreferences.TestDirectory=DeskSaveStore.TestDirectory;}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void After(){if(!SessionState.GetBool("Access09",false))return;SessionState.SetBool("Access09",false);new GameObject("AccessibilityValidation").AddComponent<AccessibilityValidationProbe>();}
}
